groovySource "LawSpecGroovy.groovy" = "// Generated by LawSpec. Do not edit.\npackage lawspec.testing\n\nimport java.lang.reflect.InvocationTargetException\nimport java.lang.reflect.Method\n\n/**\n * Runs a Java test class's JUnit tests from a Spock specification, for the\n * generated test classes a specification does not list feature by feature.\n */\nfinal class LawSpecGroovy\n{\n  private LawSpecGroovy()\n  {\n  }\n\n  /** The names of a class's JUnit test methods, sorted. */\n  static List<String> tests(Class<?> type)\n  {\n    type.declaredMethods\n      .findAll { Method method -> method.isAnnotationPresent(org.junit.jupiter.api.Test) }\n      .collect { Method method -> method.name }\n      .sort()\n  }\n\n  /** Runs one test method on a fresh instance; its failure is the feature's. */\n  static void run(Class<?> type, String name)\n  {\n    Method method = type.getDeclaredMethod(name)\n    method.accessible = true\n    def constructor = type.getDeclaredConstructor()\n    constructor.accessible = true\n    try\n    {\n      method.invoke(constructor.newInstance())\n    }\n    catch (InvocationTargetException failure)\n    {\n      throw failure.cause\n    }\n  }\n}\n"
groovySource "LawSpecRandomOrder.groovy" = "// Generated by LawSpec. Do not edit.\npackage lawspec.testing\n\nimport java.lang.annotation.ElementType\nimport java.lang.annotation.Retention\nimport java.lang.annotation.RetentionPolicy\nimport java.lang.annotation.Target\nimport org.spockframework.runtime.extension.ExtensionAnnotation\nimport org.spockframework.runtime.extension.IAnnotationDrivenExtension\nimport org.spockframework.runtime.model.SpecInfo\n\n/** order random: a specification's features in an order the run's seed chooses. */\n@Retention(RetentionPolicy.RUNTIME)\n@Target(ElementType.TYPE)\n@ExtensionAnnotation(LawSpecRandomOrderExtension)\n@interface LawSpecRandomOrder {}\n\n/** Shuffles the features by the seed LAWSPEC_SEED gives, or a new one, which it prints. */\n@groovy.transform.CompileStatic\nclass LawSpecRandomOrderExtension implements IAnnotationDrivenExtension<LawSpecRandomOrder>\n{\n  @Override\n  void visitSpecAnnotation(LawSpecRandomOrder annotation, SpecInfo spec)\n  {\n    long seed = LawSpecHarness.orderSeed()\n    def features = spec.features.sort(false) { it.name }\n    Collections.shuffle(features, new Random(seed ^ spec.reflection.name.hashCode()))\n    features.eachWithIndex { feature, index -> feature.executionOrder = index }\n    println \"order random seed ${seed} (${spec.reflection.simpleName}): \" +\n      \"LAWSPEC_SEED=${seed} replays this order\"\n  }\n}\n"
